H,V=len(hlines),len(vlines)
M=np.full((H,V),9)
for i,r in enumerate(hlines):
    for j,c in enumerate(vlines):
        v=G[r,c]
        if v!=3: M[i,j]=v
print(M)
# brute force: contiguous partitions of H lines into 5 groups, V into 3 groups
def parts(n,k):
    if k==1: yield [n]; return
    for first in range(1,n-k+2):
        for rest in parts(n-first,k-1):
            yield [first]+rest
def blocks(idxs, groups):
    out=[]; s=0
    for g in groups:
        out.append(idxs[s:s+g]); s+=g
    return out
sols=[]
for hg in parts(H,5):
  for vg in parts(V,3):
    B=np.full((5,3),9)
    R=blocks(hlines,hg); C=blocks(vlines,vg)
    for i,rr in enumerate(R):
        for j,cc in enumerate(C):
            vals=[M[hlines.index(r),vlines.index(c)] for r in rr for c in cc]
            vals=[v for v in vals if v!=9]
            if vals and len(set(vals))==1: B[i,j]=vals[0]
    if (B==O).all(): sols.append((hg,vg,R,C))
print("exact unique-rule solutions:", sols)

